    fr, fc, fv = sources[0]  # First source
    i, j = fr + 1, fc + 1
    while True:
        if not (0 <= i < rows and 0 <= j < cols):
            break
        if (i, j) in all_special_positions:
            break
        grid[i][j] = fv
        i += 1
        j += 1

